/** RDF collections are a reversible presentation of loaded statements, never replacement RDF statements. */
import { canvasGraph } from "./graph-canvas-scope.ts";
import type { Graph, GraphEdge, GraphNode, StatementLink } from "./graph-types.ts";

const RDF = "http://www.w3.org/1999/02/22-rdf-syntax-ns#";
export const RDF_FIRST = `${RDF}first`;
export const RDF_REST = `${RDF}rest`;
export const RDF_NIL = `${RDF}nil`;
const RDF_TYPE = `${RDF}type`;
const RDF_LIST = `${RDF}List`;
export const COLLECTION_PREVIEW_LIMIT = 4;
/** This predicate is used only on presentation edges and must never be exported or queried as RDF. */
export const COLLECTION_MEMBER_PREDICATE = "urn:rdf4j:workbench:collection-member";

